 20→// ParseExportSession parses export JSON content into an ExportSession structure.
 21→func ParseExportSession(data []byte) (*ExportSession, error) {
 22→	if len(data) == 0 {
 23→		return nil, nil //nolint:nilnil // nil for empty data is expected
 24→	}
 25→
 26→	var session ExportSession
 27→	if err := json.Unmarshal(data, &session); err != nil {
 28→		return nil, fmt.Errorf("failed to parse export session: %w", err)
 29→	}
 30→
 31→	return &session, nil
 32→}
 33→
 34→// parseExportSessionFromFile reads and parses an export JSON transcript file.
 35→func parseExportSessionFromFile(path string) (*ExportSession, error) {
 36→	data, err := os.ReadFile(path) //nolint:gosec // Path from agent hook
 37→	if err != nil {
 38→		return nil, err //nolint:wrapcheck // Callers check os.IsNotExist on this error
 39→	}
 40→	return ParseExportSession(data)
 41→}
