167→// extractFilePathFromInput extracts the file path from an OpenCode tool's input map.
168→// OpenCode uses camelCase keys (e.g., "filePath"), with "path" as a fallback.
169→func extractFilePathFromInput(input map[string]any) string {
170→	for _, key := range []string{"filePath", "path"} {
171→		if v, ok := input[key]; ok {
172→			if s, ok := v.(string); ok && s != "" {
173→				return s
174→			}
175→		}
176→	}
177→	return ""
178→}
