180→// ExtractPrompts extracts user prompt strings from the transcript starting at the given offset.
181→func (a *OpenCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
182→	session, err := parseExportSessionFromFile(sessionRef)
183→	if err != nil {
184→		if os.IsNotExist(err) {
185→			return nil, nil
186→		}
187→		return nil, err
188→	}
189→	if session == nil {
190→		return nil, nil
191→	}
192→
193→	var prompts []string
194→	for i := fromOffset; i < len(session.Messages); i++ {
195→		msg := session.Messages[i]
196→		if msg.Info.Role != roleUser {
197→			continue
198→		}
199→		// Extract text from parts
200→		content := ExtractTextFromParts(msg.Parts)
201→		if content != "" {
202→			prompts = append(prompts, content)
203→		}
204→	}
205→
206→	return prompts, nil
207→}
