209→// ExtractSummary extracts the last assistant message content as a summary.
210→func (a *OpenCodeAgent) ExtractSummary(sessionRef string) (string, error) {
211→	session, err := parseExportSessionFromFile(sessionRef)
212→	if err != nil {
213→		if os.IsNotExist(err) {
214→			return "", nil
215→		}
216→		return "", err
217→	}
218→	if session == nil {
219→		return "", nil
220→	}
221→
222→	for i := len(session.Messages) - 1; i >= 0; i-- {
223→		msg := session.Messages[i]
224→		if msg.Info.Role == roleAssistant {
225→			content := ExtractTextFromParts(msg.Parts)
226→			if content != "" {
227→				return content, nil
228→			}
229→		}
230→	}
231→
232→	return "", nil
233→}
