235→// ExtractTextFromParts extracts text content from message parts.
236→func ExtractTextFromParts(parts []Part) string {
237→	var texts []string
238→	for _, part := range parts {
239→		if part.Type == "text" && part.Text != "" {
240→			texts = append(texts, part.Text)
241→		}
242→	}
243→	return strings.Join(texts, "\n")
244→}
