270→// CalculateTokenUsageFromBytes computes token usage from raw export JSON transcript bytes
271→// starting at the given message offset.
272→// This is a package-level function used by the condensation path (which has bytes, not a file path).
273→func CalculateTokenUsageFromBytes(data []byte, startMessageIndex int) *agent.TokenUsage {
274→	session, err := ParseExportSession(data)
275→	if err != nil || session == nil {
276→		return &agent.TokenUsage{}
277→	}
278→
279→	usage := &agent.TokenUsage{}
280→	for i := startMessageIndex; i < len(session.Messages); i++ {
281→		msg := session.Messages[i]
282→		if msg.Info.Role != roleAssistant || msg.Info.Tokens == nil {
283→			continue
284→		}
285→		usage.InputTokens += msg.Info.Tokens.Input
286→		usage.OutputTokens += msg.Info.Tokens.Output
287→		usage.CacheReadTokens += msg.Info.Tokens.Cache.Read
288→		usage.CacheCreationTokens += msg.Info.Tokens.Cache.Write
289→		usage.APICallCount++
290→	}
291→
292→	return usage
293→}
